using System;
using System.Collections.Generic;
using System.ComponentModel.DataAnnotations;
using System.Linq;
using System.Reflection;
using Microsoft.AspNetCore.Components;

namespace Pixata.Blazor.Components.Grid;

/// <summary>
/// Marks where the automatically generated columns go among the declared ones. Only needed when you want them somewhere other
/// than after the declared columns, and the grid's <c>AutoGenerateColumns</c> must still be true
/// </summary>
public class PixataGridAutoGeneratedColumns<TItem> : PixataGridColumnBase<TItem> {
  /// <summary>
  /// The width of each generated column. If not set, they share the space left by the other columns
  /// </summary>
  [Parameter]
  public string? ColumnWidth { get; set; }

  // Only simple values make sense in a cell. A complex property would just show its type name
  private static readonly HashSet<Type> SimpleTypes = [
    typeof(string), typeof(decimal), typeof(DateTime), typeof(DateTimeOffset), typeof(DateOnly), typeof(TimeOnly), typeof(TimeSpan), typeof(Guid)
  ];

  internal static IEnumerable<PixataGridColumn<TItem>> Generate(string? columnWidth) =>
    typeof(TItem).GetProperties(BindingFlags.Public | BindingFlags.Instance)
      .Where(p => p.CanRead && p.GetIndexParameters().Length == 0 && IsSimple(p.PropertyType))
      .Select(p => (Property: p, Display: p.GetCustomAttribute<DisplayAttribute>()))
      .Where(p => p.Display?.GetAutoGenerateField() != false && p.Property.GetCustomAttribute<ScaffoldColumnAttribute>()?.Scaffold != false)
      .OrderBy(p => p.Display?.GetOrder() ?? 10000)
#pragma warning disable BL0005 // These columns are never rendered, so setting their parameters directly is safe
      .Select(p => new PixataGridColumn<TItem> { Field = p.Property.Name, Width = columnWidth });
#pragma warning restore BL0005

  private static bool IsSimple(Type type) {
    Type underlying = Nullable.GetUnderlyingType(type) ?? type;
    return underlying.IsPrimitive || underlying.IsEnum || SimpleTypes.Contains(underlying);
  }
}
